structlogger = structlog.get_logger()

# Project folder path, resolved once at startup by run_server() in
# single-folder mode (`rasa tools run`).
# All MCP tools read this via _get_project_folder().
_project_folder_path: Optional[str] = None

# Workspaces root, set instead of _project_folder_path when the server serves
# every agent the builder hosts; each tool call then names its agent.
_workspaces_root: Optional[Path] = None

# Server-level Rasa server URL, set once at startup by run_server().
# MCP tools use this as the default when the LLM does not provide an override.
