_SCENARIO_VALIDATION_FAILED = "Scenario validation failed."


def _check_slot_errors(
    initial_slots: dict,
    assertion_slot_names: list,
    assertion_slot_values: dict,
    known_slots: dict,
) -> list:
    """Return validation errors for domain-slot initial_slots and assertions."""
    from rasa.builder.copilot.mcp_server.tools.scenario import (
        check_slot_type_compatibility,
    )

    errors: list = []
    for slot_name, value in initial_slots.items():
        if slot_name not in known_slots:
            errors.append(
                f"Unknown slot '{slot_name}' in initial_slots: "
                f"not defined in the domain."
            )
            continue
        type_error = check_slot_type_compatibility(
            slot_name, value, known_slots[slot_name].type
        )
        if type_error:
            errors.append(type_error)
    for slot_name in assertion_slot_names:
        if slot_name not in known_slots:
            errors.append(
                f"Unknown slot '{slot_name}' in assertions: "
                f"not defined in the domain."
            )
            continue
        value = assertion_slot_values.get(slot_name)
        if value is not None:
            type_error = check_slot_type_compatibility(
                slot_name, value, known_slots[slot_name].type
            )
            if type_error:
                errors.append(type_error)
    return errors


def _check_initial_slots_errors(
    initial_slots: dict,
    assertion_slot_names: list,
    assertion_slot_values: dict,
    known_slots: dict,
    project_folder: str,
) -> list:
    """Validate ``initial_slots`` for Mantle seed fields and domain slots."""
    from pathlib import Path

    from rasa.builder.copilot.mcp_server.tools.scenario_initial_setup import (
        check_seed_initial_slot_errors,
        load_project_memory_schema,
        partition_initial_slots,
    )

    project_memory = load_project_memory_schema(Path(project_folder))
    errors = check_seed_initial_slot_errors(initial_slots, project_memory)
    _, post_session_start_slots = partition_initial_slots(initial_slots, project_memory)
    errors.extend(
        _check_slot_errors(
            post_session_start_slots,
            assertion_slot_names,
            assertion_slot_values,
            known_slots,
        )
    )
    return errors


@asynccontextmanager
async def dummy_progress_reporter(
    ctx: Context, interval_seconds: int = 10
) -> AsyncIterator[None]:
    """Context manager that reports progress periodically to keep MCP alive.

    Use this for long-running operations that don't have built-in progress
    reporting. It continuously increments a progress counter at regular
    intervals until the context exits.

    Args:
        ctx: The MCP context to report progress to
        interval_seconds: How often to report progress (default: 10 seconds)

    Example:
        async with dummy_progress_reporter(ctx):
            await some_long_running_operation()
    """
    cancelled = asyncio.Event()

    async def _report_progress() -> None:
        progress = 0
        while True:
            await asyncio.sleep(interval_seconds)
            if cancelled.is_set():
                return
            progress += 1
            try:
                await ctx.report_progress(progress=progress)
            except Exception:
                pass

    task = asyncio.create_task(_report_progress())
    try:
        yield
    finally:
        cancelled.set()
        task.cancel()
        # Suppress CancelledError from our deliberately cancelled task.
        # External cancellations will still propagate after this finally block.
        with suppress(asyncio.CancelledError):
            await task


# One engine-specific block of INSTRUCTIONS.md, markers included.
_ENGINE_BLOCK_PATTERN = re.compile(
    r"<!-- engine:(?P<engine_version>\w+) -->\n(?P<body>.*?)<!-- /engine -->\n",
    re.DOTALL,
)


def _load_instructions(engine_version: str = CALM_ENGINE_VERSION) -> str:
    """Load the MCP server instructions for one engine.

    INSTRUCTIONS.md marks engine-specific text with `<!-- engine:<version> -->`
    ... `<!-- /engine -->` blocks. Blocks for *engine_version* keep their text
    without the markers; blocks for any other engine are dropped.

    Args:
        engine_version: An engine version from `rasa.shared.engine_version`.

    Returns:
        The instructions text for that engine.
    """
    return _ENGINE_BLOCK_PATTERN.sub(
        lambda block: (
            block["body"] if block["engine_version"] == engine_version else ""
        ),
        INSTRUCTIONS_FILE_PATH.read_text(),
    )


# Initialize FastMCP server with metadata and configuration
_MCP_SERVER_NAME = "rasa-MCP-tools"
mcp = FastMCP(
    name=_MCP_SERVER_NAME,
    instructions=_load_instructions(),
)
instrument_mcp_tools(mcp, mcp_server=_MCP_SERVER_NAME)


@mcp.custom_route("/health", methods=["GET"])  # type: ignore[misc]
async def health_check(request: Request) -> JSONResponse:
    """Health endpoint for the MCP server.

    Available for HTTP transports only. Routes registered via @mcp.custom_route
    are excluded from auth requirements, making this safe to use as a
    lightweight liveness probe.

    Returns:
        JSONResponse with {"status": "ok"}
    """
    return JSONResponse({"status": "ok"})


def adapt_server_for_mantle(project_folder: str) -> None:
    """Remove CALM-v1-only tools and instructions from the server for Mantle.

    Single-folder mode only, called at startup from _set_project_folder. With
    a workspaces root every agent shares this registry, so Copilot v2 filters
    the tools per run instead (see _offers_mcp_tool in
    rasa.builder.copilot.pydantic_ai.agent). Repeat calls are harmless -
    mcp.remove_tool() raises ToolError for an already-removed tool, which is
    suppressed below.

    mcp.remove_tool() both drops the tool from tools/list and makes a direct
    call to it raise a ToolError, so no separate call-time check is needed.
    The Mantle instructions replace the CALM ones before any client connects,
    so no client is told about the removed tools.
    """
    if not has_mantle_project_layout(Path(project_folder).resolve()):
        return

    for tool_name in MCP_V1_ONLY_TOOL_NAMES:
        with suppress(ToolError):
            mcp.remove_tool(tool_name)

    # FastMCP exposes instructions read-only; the low-level server sends this
    # attribute in every initialize response.
    mcp._mcp_server.instructions = _load_instructions(MANTLE_ENGINE_VERSION)

    structlogger.info(
        "mcp_server.server.mantle_tools_hidden",
        event_info="Hid CALM-v1-only tools and instructions for a Mantle project",
        hidden_tool_count=len(MCP_V1_ONLY_TOOL_NAMES),
    )


def _set_project_folder(folder: Optional[str]) -> None:
    """Store the project folder path for use by MCP tools.

    Falls back to the RASA_PROJECT_FOLDER environment variable when *folder*
    is not provided.  Call this once at startup; tools read the stored value
    via _get_project_folder().
    """
    global _project_folder_path
    _project_folder_path = folder or os.getenv(RASA_PROJECT_FOLDER_ENV_VAR)
    if _project_folder_path is not None:
        adapt_server_for_mantle(_project_folder_path)


def _set_workspaces_root(root: str) -> None:
    """Store the workspaces root for use by MCP tools.

    Call this once at startup instead of _set_project_folder() when the
    server serves every agent workspace under *root*. Unlike
    _set_project_folder() it hides no tools, since every agent shares the
    registry.
    """
    global _workspaces_root
    _workspaces_root = Path(root).resolve()


def _workspace_folder_for_current_call(root: Path) -> Path:
    """Resolve the project folder for the tool call in progress, under *root*.

    Reads the agent id, and optionally the branch, from the current call's
    request `_meta` (the contextvar set by the MCP server for the duration of
    the call), so each concurrent call resolves its own workspace
    independently. Without a branch the call acts on the agent's `main`
    checkout. The checkout of another branch is created by the builder, never
    here, so it must already exist.

    Raises:
        RasaException: If the call carries no `_meta.agent_id`, the id is not a
            valid agent id, `_meta.branch` is not a valid branch name, or the
            workspace has no folder.
    """
    request_context = request_ctx.get(None)
    meta = (
        (request_context.meta.model_extra or {})
        if request_context is not None and request_context.meta is not None
        else {}
    )
    agent_id = meta.get(MCP_META_AGENT_ID)
    if not isinstance(agent_id, str) or not agent_id:
        raise RasaException(
            "This MCP server serves several agents, so every tool call "
            f"must name one in _meta.{MCP_META_AGENT_ID}."
        )

    # Lazy import: server.py keeps heavy imports out of module scope.
    from rasa.builder.exceptions import InvalidAgentIdError, InvalidBranchNameError
    from rasa.builder.workspace import (
        DEFAULT_BRANCH,
        validate_agent_id,
        validate_branch_name,
        workspace_folder,
    )

    branch = meta.get(MCP_META_BRANCH, DEFAULT_BRANCH)
    try:
        validate_agent_id(agent_id)
        validate_branch_name(branch if isinstance(branch, str) else "")
    except (InvalidAgentIdError, InvalidBranchNameError) as exc:
        raise RasaException(str(exc)) from exc

    folder = workspace_folder(root, agent_id, branch)
    if not folder.is_dir():
        raise RasaException(f"Agent '{agent_id}' has no workspace.")

    return folder


def _set_rasa_server_url(url: Optional[str]) -> None:
    """Store the Rasa server URL for use by MCP tools.

    Call this once at startup; tools read the stored value via
    _get_rasa_server_url().
    """
    global _rasa_server_url
    _rasa_server_url = url or DEFAULT_RASA_SERVER_URL


def _get_rasa_server_url() -> str:
    """Return the Rasa server URL stored by _set_rasa_server_url."""
    return _rasa_server_url or DEFAULT_RASA_SERVER_URL


def _get_project_folder() -> str:
    """Return the project folder for the tool call in progress.

    In workspaces mode (_set_workspaces_root was called) this resolves the
    calling agent's folder from the current call's _meta, so each call may see
    a different folder. In single-folder mode it returns the folder stored by
    _set_project_folder, the same for every call.

    Returns:
        Project folder path as string

    Raises:
        RasaException: In workspaces mode, if the call names no valid agent or
            that agent has no workspace folder. In single-folder mode, if
            _set_project_folder has not been called or neither the argument
            nor the RASA_PROJECT_FOLDER env var was set.
    """
    if _workspaces_root is not None:
        return str(_workspace_folder_for_current_call(_workspaces_root))

    if _project_folder_path is None:
        raise RasaException(
            "Project folder not configured. Ensure run_server() is called with "
            f"a project_folder argument or the {RASA_PROJECT_FOLDER_ENV_VAR} "
            "environment variable is set before the server starts."
        )

    return _project_folder_path


