@mcp.tool(
    name=MCP_TOOL_VALIDATE_PROJECT,
    description="Validate the assistant project configuration and training data",
    annotations={
        "title": "Validate Project",
        "readOnlyHint": True,  # Only validates, doesn't modify
        "openWorldHint": False,
        "idempotentHint": True,
    },
    structured_output=True,
)
async def validate_project(ctx: Context) -> ValidationResponse:
    """Validate the assistant project configuration and training data.

    Runs comprehensive validation checks on domain, flows, config, and training data.
    This operation can take 60+ seconds for large projects.
    Always run this after making changes before training.
    """
    from rasa.builder.copilot.mcp_server.tools.validation_training import (
        validate_assistant_project,
    )

    await ctx.info("Starting project validation...")
    project_folder = _get_project_folder()

    result = await validate_assistant_project(project_folder)

    await ctx.info("Validation complete")
    return result


@mcp.tool(
    name=MCP_TOOL_VALIDATE_SCENARIO,
    description=("Validate a scenario YAML file for syntax and assertion correctness."),
    annotations={
        "title": "Validate Scenario",
        "readOnlyHint": True,
        "openWorldHint": False,
        "idempotentHint": True,
    },
    structured_output=True,
)
async def validate_scenario(
    ctx: Context,
    scenario_path: Annotated[
        str,
        Field(description="Relative path to the scenario YAML file within the project"),
    ],
    domain_folder: Annotated[
        Optional[str],
        Field(
            description=(
                "Folder containing domain YAML files, relative to project root. "
                "Defaults to 'domain'. Used to verify that slot names in "
                "initial_slots are defined in the domain."
            )
        ),
    ] = "domain",
) -> ScenarioValidationResponse:
    """Validate a scenario YAML file for syntax and assertion correctness."""
    from rasa.builder.copilot.mcp_server.tools.project_context import (
        list_project_slots,
    )
    from rasa.builder.copilot.mcp_server.tools.scenario import (
        EvalScenarioError,
        get_assertion_slot_names,
        get_assertion_slot_values,
        load_scenario,
    )
    from rasa.builder.copilot.mcp_server.tools.utils import validate_subfolder_path
    from rasa.utils.io import InvalidPathException

    await ctx.info("Validating scenario...")
    project_folder = _get_project_folder()

    try:
        path = validate_subfolder_path(Path(project_folder).resolve(), scenario_path)
    except InvalidPathException as exc:
        return ScenarioValidationResponse(
            success=False,
            errors=[str(exc)],
            message=_SCENARIO_VALIDATION_FAILED,
        )

    try:
        scenario = load_scenario(path)
    except EvalScenarioError as exc:
        return ScenarioValidationResponse(
            success=False,
            errors=[str(exc)],
            message=_SCENARIO_VALIDATION_FAILED,
        )

    errors: list[str] = []

    assertion_slot_names = get_assertion_slot_names(scenario.goals.assertions)
    needs_domain_check = bool(scenario.setup.initial_slots or assertion_slot_names)
    # Mantle (CALM v2) projects have no domain/slots concept, so
    # list_project_slots would legitimately find zero slots and every
    # asserted slot name would be flagged as "unknown" - a false positive.
    # Skip the domain-bound check there instead of misreporting.
    is_mantle = has_mantle_project_layout(Path(project_folder).resolve())

    if needs_domain_check and not is_mantle:
        slots_response = await list_project_slots(project_folder, domain_folder)
        if slots_response.success:
            known_slots = {slot.name: slot for slot in slots_response.slots}
            assertion_slot_values = get_assertion_slot_values(scenario.goals.assertions)
            errors.extend(
                _check_initial_slots_errors(
                    scenario.setup.initial_slots,
                    assertion_slot_names,
                    assertion_slot_values,
                    known_slots,
                    project_folder,
                )
            )
        else:
            errors.append(f"Could not load domain slots: {slots_response.error}")

    if errors:
        return ScenarioValidationResponse(
            success=False,
            errors=errors,
            message=_SCENARIO_VALIDATION_FAILED,
        )

    await ctx.info("Scenario validation complete.")
    return ScenarioValidationResponse(
        success=True,
        errors=[],
        message="Scenario is valid.",
    )


@mcp.tool(
    name=MCP_TOOL_TRAIN_RASA_ASSISTANT,
    description="Train the Rasa assistant with the current project configuration",
    annotations={
        "title": "Train Rasa Assistant",
        "readOnlyHint": False,  # Creates model files
        "destructiveHint": False,  # Doesn't overwrite existing models
        "idempotentHint": False,  # Each training may produce different results
        "openWorldHint": False,
    },
    structured_output=True,
)
async def train_rasa_assistant(ctx: Context) -> TrainingResponse:
    """Train the Rasa assistant with the current project configuration.

    This trains a new model using the current domain, flows, and training data.
    Training can take several minutes for large projects.
    Only call this after validation passes successfully.
    """
    from rasa.builder.copilot.mcp_server.tools.validation_training import (
        train_assistant,
    )

    await ctx.info("Starting model training...")
    project_folder = _get_project_folder()

    async with dummy_progress_reporter(ctx):
        result = await train_assistant(project_folder)

    await ctx.info("Training complete")
    return result


