@mcp.tool(
    name=MCP_TOOL_EVALUATE_AGENT,
    description=(
        "Run goal-driven evaluations against a running Rasa assistant. "
        "Takes one or more scenarios and runs them concurrently. "
        "Loads eval/conftest.yml for LLM configuration, simulates each "
        "conversation using an LLM-as-user, evaluates deterministic assertions "
        "against tracker events, and scores qualitative criteria with an LLM "
        "judge. Results are written to eval/results/<experiment_timestamp>/. "
        "A run is marked passed only when all assertions and all scenario criteria "
        "pass. Quality metrics (helpfulness, coherence, task_completion, etc.) are "
        "recorded for observability but do not gate the pass/fail verdict — add a "
        "criterion if a metric outcome must be a hard requirement."
    ),
    annotations={
        "title": "Evaluate Agent",
        "readOnlyHint": False,  # Writes result files to disk
        "openWorldHint": False,
        "idempotentHint": False,
    },
    structured_output=True,
)
async def evaluate_agent(
    ctx: Context,
    scenario_paths: Annotated[
        List[str],
        Field(
            description=(
                "Relative paths to the scenario YAML files within the project "
                "(e.g. "
                "['eval/scenarios/happy_path/card_replace_damaged_happy.yml']). "
                "Pass every scenario for this session in a single call: they "
                "are evaluated concurrently and share one experiment summary. "
                "A single scenario is just a one-element list."
            )
        ),
    ],
    experiment_timestamp: Annotated[
        str,
        Field(
            description=(
                "Experiment folder name (e.g. '2026-04-21_14-30-22'). "
                "Generated once per invocation with "
                "datetime.now().strftime('%Y-%m-%d_%H-%M-%S') and shared across all "
                "evaluate_agent calls so every scenario lands under "
                "eval/results/<experiment_timestamp>/. "
                "Use scenario_paths for several scenarios and run_count for "
                "repeat runs — do not call evaluate_agent twice for the same "
                "scenario with the same timestamp."
            ),
        ),
    ],
    run_count: Annotated[
        int,
        Field(
            description=(
                "Number of times to run each scenario. "
                "Multiple runs surface flakiness in LLM-driven conversations. "
                "This multiplies with the number of scenarios: the batch is "
                "run_count x len(scenario_paths) executions, so raise it and "
                "the scenario count together with care."
            ),
            ge=1,
            le=10,
        ),
    ] = 1,
    parallelism: Annotated[
        int,
        Field(
            description=(
                "Maximum number of (scenario, run) executions in flight at "
                "once across the whole batch. One execution is many LLM "
                "calls, not one: a simulation-role call per turn (up to "
                f"{SIMULATOR_MAX_TURNS}), the agent's own calls behind "
                "each turn, then one or two evaluation-role calls. Raise it "
                "only when both the Rasa server and the LLM provider have "
                "headroom."
            ),
            ge=1,
            le=MAX_EVAL_PARALLELISM,
        ),
    ] = DEFAULT_EVAL_PARALLELISM,
    rasa_server_url: Annotated[
        Optional[str],
        Field(
            description=(
                "Base URL of the running Rasa server (e.g. http://localhost:5005). "
                "Leave empty to use the server URL configured at startup."
            ),
        ),
    ] = None,
    show_tracker_events: Annotated[
        bool,
        Field(
            description=(
                "When true, append important tracker events grouped by user turn "
                "to the Tracker Events section of each run_N.txt report. Use this "
                "to diagnose where a conversation went off track. Off by default; "
                "it only adds report detail and does not change pass/fail."
            ),
        ),
    ] = False,
) -> EvaluateAgentResponse:
    """Run evaluation scenarios and write per-run reports and experiment summary."""
    from rasa.builder.copilot.mcp_server.tools.artifact_writer import (
        safe_name,
        write_experiment_summary,
    )
    from rasa.builder.copilot.mcp_server.tools.eval_config import (
        EvalConfigError,
        build_llm_client,
        load_conftest,
        load_prompt_template,
    )
    from rasa.builder.copilot.mcp_server.tools.evaluate_agent import run_scenarios
    from rasa.builder.copilot.mcp_server.tools.scenario import (
        EvalScenarioError,
        load_scenario,
    )
    from rasa.builder.copilot.mcp_server.tools.utils import validate_subfolder_path
    from rasa.utils.io import InvalidPathException

    project_path = Path(_get_project_folder()).resolve()

    if not scenario_paths:
        return EvaluateAgentResponse(
            success=False,
            message=_SCENARIO_VALIDATION_FAILED,
            error="scenario_paths must contain at least one scenario path.",
        )

    if len(scenario_paths) > MAX_SCENARIOS_PER_BATCH:
        return EvaluateAgentResponse(
            success=False,
            message=_SCENARIO_VALIDATION_FAILED,
            error=(
                f"Too many scenarios in one call: got {len(scenario_paths)}, "
                f"maximum is {MAX_SCENARIOS_PER_BATCH}. Split them across "
                "several calls sharing one experiment_timestamp."
            ),
        )

    try:
        safe_name(experiment_timestamp)
    except ValueError as exc:
        return EvaluateAgentResponse(
            success=False,
            message="Invalid experiment_timestamp.",
            error=str(exc),
        )

    try:
        conftest = load_conftest(project_path)
    except EvalConfigError as exc:
        return EvaluateAgentResponse(
            success=False, message="Could not load eval/conftest.yml.", error=str(exc)
        )

    try:
        simulation_llm_client = build_llm_client(conftest.simulation.llm)
        eval_llm_client = build_llm_client(conftest.evaluation.llm)
    except EvalConfigError as exc:
        return EvaluateAgentResponse(
            success=False, message="Could not build LLM client.", error=str(exc)
        )

    simulated_user_prompt: Optional[str] = None
    if conftest.simulation.simulated_user_prompt:
        try:
            simulated_user_prompt = load_prompt_template(
                project_path, conftest.simulation.simulated_user_prompt
            )
        except EvalConfigError as exc:
            return EvaluateAgentResponse(
                success=False,
                message="Could not load simulation prompt template.",
                error=str(exc),
            )

    criteria_judge_prompt: Optional[str] = None
    if conftest.evaluation.criteria_judge_prompt:
        try:
            criteria_judge_prompt = load_prompt_template(
                project_path, conftest.evaluation.criteria_judge_prompt
            )
        except EvalConfigError as exc:
            return EvaluateAgentResponse(
                success=False,
                message="Could not load criteria judge prompt template.",
                error=str(exc),
            )

    metrics_judge_prompt: Optional[str] = None
    if conftest.evaluation.metrics_judge_prompt:
        try:
            metrics_judge_prompt = load_prompt_template(
                project_path, conftest.evaluation.metrics_judge_prompt
            )
        except EvalConfigError as exc:
            return EvaluateAgentResponse(
                success=False,
                message="Could not load metrics judge prompt template.",
                error=str(exc),
            )

    # Every path is validated and loaded up front: a typo in the last path
    # should fail before any run starts, not after the batch has already
    # spent LLM calls on the earlier ones.
    scenarios = []
    slug_origin: Dict[str, str] = {}
    for scenario_path in scenario_paths:
        try:
            validated_path = validate_subfolder_path(project_path, scenario_path)
            scenario = load_scenario(validated_path)
            safe_name(scenario.slug)
        except (InvalidPathException, EvalScenarioError, ValueError) as exc:
            return EvaluateAgentResponse(
                success=False,
                message=_SCENARIO_VALIDATION_FAILED,
                error=f"{scenario_path}: {exc}",
            )
        # A scenario's slug is its filename stem, and both the per-run report
        # directory and the summary are keyed on it. Two paths with the same
        # basename would therefore overwrite each other's run files and drop
        # one entry from the summary, with nothing reported. Reject instead.
        # Compared case-insensitively: macOS and Windows filesystems would
        # collide 'Happy_Path' with 'happy_path' even though the slugs differ.
        slug_key = scenario.slug.casefold()
        if slug_key in slug_origin:
            return EvaluateAgentResponse(
                success=False,
                message=_SCENARIO_VALIDATION_FAILED,
                error=(
                    f"Duplicate scenario name '{scenario.slug}': "
                    f"'{slug_origin[slug_key]}' and '{scenario_path}' "
                    "would write to the same results folder and overwrite "
                    "each other. Rename one or evaluate them separately."
                ),
            )
        slug_origin[slug_key] = scenario_path
        scenarios.append(scenario)

    resolved_url = rasa_server_url or _get_rasa_server_url()

    await ctx.info(
        f"Running {len(scenarios)} scenario(s) × {run_count} "
        f"at parallelism {parallelism} (experiment: {experiment_timestamp})..."
    )

    # run_scenarios owns the batch timeout internally so that exhausting it
    # degrades to partial results; the summary below is written either way.
    async with dummy_progress_reporter(ctx):
        summary_entries, batch_elapsed_s = await run_scenarios(
            scenarios=scenarios,
            project_path=project_path,
            experiment_timestamp=experiment_timestamp,
            run_count=run_count,
            parallelism=parallelism,
            rasa_server_url=resolved_url,
            simulation_llm_client=simulation_llm_client,
            eval_llm_client=eval_llm_client,
            eval_llm_config=conftest.evaluation.llm,
            simulated_user_prompt=simulated_user_prompt,
            criteria_judge_prompt=criteria_judge_prompt,
            metrics_judge_prompt=metrics_judge_prompt,
            show_tracker_events=show_tracker_events,
            simulation_max_concurrent_llm_calls=(
                conftest.simulation.max_concurrent_llm_calls
            ),
            eval_max_concurrent_llm_calls=(
                conftest.evaluation.max_concurrent_llm_calls
            ),
        )

    # Called exactly once per invocation regardless of batch size, which is
    # what keeps summary.json's read-modify-write free of concurrent writers.
    try:
        summary_path = write_experiment_summary(
            project_path,
            experiment_timestamp,
            summary_entries,
            wall_clock_s=batch_elapsed_s,
        )
    except Exception as exc:
        return EvaluateAgentResponse(
            success=False,
            message="Could not write experiment summary.",
            error=str(exc),
        )

    runs_passed = sum(entry.runs_passed for entry in summary_entries)
    runs_total = sum(entry.runs_total for entry in summary_entries)
    runs_errored = sum(entry.runs_errored for entry in summary_entries)

    message = (
        f"{runs_passed}/{runs_total} runs passed "
        f"across {len(summary_entries)} scenario(s)."
    )
    # Nothing was evaluated, so there is no verdict on the agent to report.
    # Before this tool ran scenarios concurrently a timed-out batch returned
    # success=False; keeping that for the total-failure case stops "0/N passed"
    # from reading as a regression in the agent under test. A batch where some
    # runs did complete stays successful -- those results are still worth
    # having, and runs_errored carries the caveat.
    nothing_ran = runs_total > 0 and runs_errored == runs_total
    if runs_errored:
        # Counted as failures, but the cause is the evaluation harness rather
        # than the agent -- say so, or the caller reads it as a regression.
        message += (
            f" {runs_errored} run(s) failed for harness reasons (timed out, "
            "cancelled, or errored) rather than on their merits; each still "
            "has a run file recording what happened."
        )

    await ctx.info(
        f"Evaluation complete: {runs_passed}/{runs_total} runs passed. "
        f"Summary: {summary_path.as_posix()}"
    )

    return EvaluateAgentResponse(
        success=not nothing_ran,
        error=(
            "Every requested run timed out or errored; nothing was evaluated."
            if nothing_ran
            else None
        ),
        experiment_timestamp=experiment_timestamp,
        scenario_results=[
            ScenarioResultSummary(
                scenario_name=entry.scenario_name,
                runs_total=entry.runs_total,
                runs_passed=entry.runs_passed,
                runs_errored=entry.runs_errored,
            )
            for entry in summary_entries
        ],
        summary_path=summary_path.as_posix(),
        message=message,
    )


