# RESOURCES - File-like static data that can be read by clients
# ============================================================================

# Note: Dynamic resource templates (uri_template) are not
# supported in mcp.server.fastmcp


# ============================================================================
# SERVER INITIALIZATION
# ============================================================================


def run_server(
    host: str = MCP_DEFAULT_HOST,
    port: int = MCP_DEFAULT_PORT,
    transport: str = MCP_TRANSPORT_STREAMABLE_HTTP,
    project_folder: Optional[str] = None,
    rasa_server_url: Optional[str] = None,
    workspaces_root: Optional[str] = None,
) -> None:
    """Run the MCP server.

    This is the entry point for the MCP server. It can be started standalone
    via `rasa tools run` or embedded alongside the Sanic server (builder mode).

    The resolved project folder (or workspaces root) is stored as module-level
    state so that MCP tools can access it via _get_project_folder() without
    reading environment variables at request time.

    IMPORTANT: When using stdio transport, the caller MUST ensure all logging
    goes to stderr, not stdout. The MCP stdio protocol requires stdout to
    contain ONLY JSON-RPC messages. Any other output will corrupt the protocol
    and break IDE client connections.

    Args:
        host: Host to bind the server to (only used for streamable-http).
        port: Port to bind the server to (only used for streamable-http).
        transport: FastMCP transport to use – MCP_TRANSPORT_STDIO or
            MCP_TRANSPORT_STREAMABLE_HTTP (default: MCP_TRANSPORT_STREAMABLE_HTTP
            for backward compatibility with the embedded builder server).
        project_folder: Path to the Rasa project folder, for single-folder
            mode. Ignored when workspaces_root is given. If neither is
            provided, falls back to the RASA_PROJECT_FOLDER environment
            variable.
        rasa_server_url: Base URL of the running Rasa server
            (e.g. ``http://localhost:5005``).  Stored as the server-level default that
            MCP tools use when the caller (LLM) does not provide an explicit override.
            - `rasa tools run` passes the value from `RunConfig` (default
              `http://localhost:5005`);
            - builder mode passes the co-hosted builder URL.
        workspaces_root: Root folder holding one sub-folder per agent. When
            given, the server serves every agent workspace under it instead
            of a single project_folder, and each tool call must name its
            agent in `_meta` (MCP_META_AGENT_ID) for _get_project_folder() to
            resolve.
    """
    try:
        if workspaces_root is not None:
            _set_workspaces_root(workspaces_root)
            serves = {"workspaces_root": str(_workspaces_root)}
        else:
            _set_project_folder(project_folder)
            serves = {"project_folder": _get_project_folder()}
        _set_rasa_server_url(rasa_server_url)

        structlogger.info(
            "mcp_server.server.starting",
            event_info="Starting MCP server",
            transport=transport,
            host=host if transport != MCP_TRANSPORT_STDIO else None,
            port=port if transport != MCP_TRANSPORT_STDIO else None,
            **serves,
        )

        if transport == MCP_TRANSPORT_STDIO:
            structlogger.info(
                "mcp_server.server.ready",
                event_info="MCP server ready (stdio mode)",
                transport=transport,
            )
            mcp.run(transport=MCP_TRANSPORT_STDIO)
        else:
            mcp.settings.host = host
            mcp.settings.port = port
            structlogger.info(
                "mcp_server.server.ready",
                event_info="MCP server ready (http mode)",
                transport=transport,
                host=host,
                port=port,
                url=MCP_HTTP_URL_PATTERN.format(host=host, port=port),
                health_url=MCP_HTTP_HEALTH_URL_PATTERN.format(host=host, port=port),
            )
            mcp.run(transport=MCP_TRANSPORT_STREAMABLE_HTTP)

    except Exception as e:
        structlogger.error(
            "mcp_server.server.startup_error",
            event_info="Failed to start MCP server",
            error=str(e),
        )
        import sys

        sys.exit(1)
